import React, { useMemo, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { BillingData } from '../types';
import { exportToExcel } from '../services/excelUtils';
import Card from './common/Card';

interface DashboardTabProps {
  data: BillingData;
}

const formatNumber = (value: number, decimals: number = 2) => {
    if (typeof value !== 'number' || isNaN(value)) return '0.00';
    return new Intl.NumberFormat('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }).format(value);
};

const DashboardTab: React.FC<DashboardTabProps> = ({ data }) => {
  const sortedData = useMemo(() => [...data].sort((a, b) => a.month.localeCompare(b.month)), [data]);
  const months = useMemo(() => sortedData.map(d => d.month), [sortedData]);

  // 新增狀態：用於詳細分析的選擇月份與展開的帳號
  const [focusMonth, setFocusMonth] = useState<string>(months[months.length - 1] || '');
  const [expandedAccountId, setExpandedAccountId] = useState<string | null>(null);

  const monthlyTotalData = useMemo(() => {
    return sortedData.map(monthData => ({
      month: monthData.month,
      'Total Amount of Payment (USD)': monthData.totalAmount,
    }));
  }, [sortedData]);

  const totalCumulativeAmount = useMemo(() => {
    return sortedData.reduce((sum, monthData) => sum + monthData.totalAmount, 0);
  }, [sortedData]);

  const accountChanges = useMemo(() => {
    if (sortedData.length < 1) return [];

    const changes = [];

    for (let i = 1; i < sortedData.length; i++) {
      const prevMonthData = sortedData[i - 1];
      const currentMonthData = sortedData[i];
      const prevAccounts = new Set(prevMonthData.accounts.map(acc => acc.accountId));
      const currentAccounts = new Set(currentMonthData.accounts.map(acc => acc.accountId));

      const newAccounts = [...currentAccounts].filter(id => !prevAccounts.has(id)).map(id => {
        const account = currentMonthData.accounts.find(acc => acc.accountId === id);
        return { id, name: account?.accountName || 'N/A' };
      });

      const removedAccounts = [...prevAccounts].filter(id => !currentAccounts.has(id)).map(id => {
        const account = prevMonthData.accounts.find(acc => acc.accountId === id);
        return { id, name: account?.accountName || 'N/A' };
      });

      changes.push({
        month: currentMonthData.month,
        prevCount: prevAccounts.size,
        currentCount: currentAccounts.size,
        newAccounts,
        removedAccounts
      });
    }

    return changes;
  }, [sortedData]);

  const perAccountChangesData = useMemo(() => {
    const allAccounts = new Map<string, { accountName: string; monthlyTotals: { [month: string]: number } }>();

    sortedData.forEach(monthData => {
      monthData.accounts.forEach(account => {
        if (!allAccounts.has(account.accountId)) {
          allAccounts.set(account.accountId, { accountName: account.accountName, monthlyTotals: {} });
        }
        const acc = allAccounts.get(account.accountId)!;
        acc.monthlyTotals[monthData.month] = account.totalAmount;
      });
    });

    return Array.from(allAccounts.entries()).map(([accountId, data]) => ({
      accountId,
      accountName: data.accountName,
      monthlyTotals: data.monthlyTotals
    }));
  }, [sortedData]);

  // 計算特定帳號在 focusMonth 的產品明細
  const getAccountServiceDetails = (accountId: string) => {
    const currentMonthData = sortedData.find(d => d.month === focusMonth);
    const prevMonthIndex = months.indexOf(focusMonth) - 1;
    const prevMonth = prevMonthIndex >= 0 ? months[prevMonthIndex] : null;
    const prevMonthData = prevMonth ? sortedData.find(d => d.month === prevMonth) : null;

    const currentAccount = currentMonthData?.accounts.find(a => a.accountId === accountId);
    const prevAccount = prevMonthData?.accounts.find(a => a.accountId === accountId);

    const services = new Map<string, { current: number; prev: number }>();

    currentAccount?.services.forEach(s => {
      services.set(s.productName, { current: s.totalCost, prev: 0 });
    });

    prevAccount?.services.forEach(s => {
      const existing = services.get(s.productName) || { current: 0, prev: 0 };
      services.set(s.productName, { ...existing, prev: s.totalCost });
    });

    return Array.from(services.entries())
      .map(([name, costs]) => ({
        productName: name,
        currentCost: costs.current,
        prevCost: costs.prev,
        diff: costs.current - costs.prev
      }))
      .sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff));
  };

  const handleExport = () => {
      const exportData = perAccountChangesData.map(account => {
        const row: any = {
          'Account ID': account.accountId,
          'Account Name': account.accountName,
        };

        months.forEach((month, index) => {
          const total = account.monthlyTotals[month] ?? 0;
          row[`${month} (USD)`] = total.toFixed(2);

          if (index > 0) {
            const prevMonth = months[index - 1];
            const prevTotal = account.monthlyTotals[prevMonth] ?? 0;
            const mom = total - prevTotal;
            const momPercent = prevTotal !== 0 ? (mom / prevTotal) * 100 : 0;
            row[`${month} MoM (USD)`] = mom.toFixed(2);
            row[`${month} MoM (%)`] = momPercent.toFixed(2);
          }
        });
        return row;
      });

      if (exportData.length > 0) {
        exportToExcel(exportData, `account_cost_changes`);
      } else {
        alert("沒有可匯出的資料。");
      }
  };

  return (
    <div className="space-y-8">
      <Card title="總覽與每月趨勢">
        <div className="mb-6 p-4 bg-gray-700 rounded-lg">
          <h4 className="text-lg font-semibold text-white">累計總支付金額 (Total Amount of Payment)</h4>
          <p className="text-3xl font-bold text-blue-400">{formatNumber(totalCumulativeAmount)} (USD)</p>
        </div>
        <div className="h-96">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={monthlyTotalData} margin={{ top: 5, right: 30, left: 50, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#4a5568" />
              <XAxis dataKey="month" stroke="#a0aec0" />
              <YAxis stroke="#a0aec0" tickFormatter={(value) => Number(value).toLocaleString()} />
              <Tooltip
                contentStyle={{ backgroundColor: '#2d3748', border: 'none', borderRadius: '0.5rem' }}
                labelStyle={{ color: '#e2e8f0' }}
                formatter={(value:number) => [formatNumber(value), 'Total Amount of Payment']}
              />
              <Legend wrapperStyle={{color: '#a0aec0'}} />
              <Line type="monotone" dataKey="Total Amount of Payment (USD)" stroke="#4299e1" strokeWidth={2} activeDot={{ r: 8 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </Card>

      <Card title="每月帳號數量變化">
        <div className="overflow-x-auto">
            <table className="w-full text-sm text-left text-gray-400">
                <thead className="text-xs text-gray-300 uppercase bg-gray-700">
                    <tr>
                        <th scope="col" className="px-6 py-3">月份</th>
                        <th scope="col" className="px-6 py-3 text-right">帳號總數</th>
                        <th scope="col" className="px-6 py-3 text-right">數量變化</th>
                        <th scope="col" className="px-6 py-3">新增帳號</th>
                        <th scope="col" className="px-6 py-3">移除帳號</th>
                    </tr>
                </thead>
                <tbody>
                    {sortedData.length > 0 && (
                      <tr className="bg-gray-800 border-b border-gray-700">
                        <td className="px-6 py-4">{sortedData[0].month} (基準)</td>
                        <td className="px-6 py-4 text-right">{sortedData[0].accounts.length}</td>
                        <td className="px-6 py-4 text-right">-</td>
                        <td className="px-6 py-4">-</td>
                        <td className="px-6 py-4">-</td>
                      </tr>
                    )}
                    {accountChanges.map(change => (
                        <tr key={change.month} className="bg-gray-800 border-b border-gray-700">
                            <td className="px-6 py-4 font-medium text-white">{change.month}</td>
                            <td className="px-6 py-4 text-right">{change.currentCount}</td>
                            <td className={`px-6 py-4 text-right font-semibold ${change.currentCount > change.prevCount ? 'text-green-400' : change.currentCount < change.prevCount ? 'text-red-400' : ''}`}>
                                {change.currentCount - change.prevCount > 0 ? '+' : ''}{change.currentCount - change.prevCount}
                            </td>
                            <td className="px-6 py-4">{change.newAccounts.length > 0 ? change.newAccounts.map(a => `${a.name} (${a.id})`).join(', ') : '無'}</td>
                            <td className="px-6 py-4">{change.removedAccounts.length > 0 ? change.removedAccounts.map(a => `${a.name} (${a.id})`).join(', ') : '無'}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
      </Card>

      <Card title="每個帳號的金額變化" actionButton={perAccountChangesData.length > 0 && <button onClick={handleExport} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded text-sm transition-colors">匯出 Excel</button>}>
        <div className="mb-4 p-4 bg-gray-700 rounded-lg flex items-center space-x-4">
            <label htmlFor="focus-month-select" className="text-sm font-medium text-gray-300">分析基準月份:</label>
            <select
                id="focus-month-select"
                value={focusMonth}
                onChange={(e) => {
                    setFocusMonth(e.target.value);
                    setExpandedAccountId(null);
                }}
                className="bg-gray-800 border border-gray-600 text-white text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2"
            >
                {months.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
            <span className="text-xs text-gray-400">點擊下方帳號列可展開查看該月份之產品費用明細</span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left text-gray-400">
            <thead className="text-xs text-gray-300 uppercase bg-gray-700 sticky top-0">
              <tr>
                <th scope="col" className="px-4 py-3">Account ID</th>
                <th scope="col" className="px-4 py-3">Account Name</th>
                {months.map((month, index) => (
                  <React.Fragment key={month}>
                    <th scope="col" className="px-4 py-3 text-right">{month} (USD)</th>
                    {index > 0 && <th scope="col" className="px-4 py-3 text-right">MoM (USD)</th>}
                    {index > 0 && <th scope="col" className="px-4 py-3 text-right">MoM (%)</th>}
                  </React.Fragment>
                ))}
              </tr>
            </thead>
            <tbody>
              {perAccountChangesData.map(account => {
                const isExpanded = expandedAccountId === account.accountId;
                return (
                  <React.Fragment key={account.accountId}>
                    <tr 
                        className={`bg-gray-800 border-b border-gray-700 hover:bg-gray-700 cursor-pointer transition-colors ${isExpanded ? 'bg-gray-750' : ''}`}
                        onClick={() => setExpandedAccountId(isExpanded ? null : account.accountId)}
                    >
                        <td className="px-4 py-4 font-medium text-white whitespace-nowrap">
                            <span className={`inline-block w-4 transition-transform duration-200 ${isExpanded ? 'rotate-90' : ''}`}>▶</span>
                            <span className="ml-2">{account.accountId}</span>
                        </td>
                        <td className="px-4 py-4 text-gray-300">{account.accountName}</td>
                        {months.map((month, index) => {
                            const total = account.monthlyTotals[month] ?? 0;
                            let mom, momPercent, momColor;
                            if (index > 0) {
                            const prevMonth = months[index - 1];
                            const prevTotal = account.monthlyTotals[prevMonth] ?? 0;
                            mom = total - prevTotal;
                            momPercent = prevTotal !== 0 ? (mom / prevTotal) * 100 : 0;
                            momColor = mom > 0 ? 'text-red-400' : mom < 0 ? 'text-green-400' : 'text-gray-400';
                            }
                            return (
                            <React.Fragment key={month}>
                                <td className="px-4 py-4 text-right">{formatNumber(total)}</td>
                                {index > 0 && <td className={`px-4 py-4 text-right ${momColor}`}>{mom !== undefined ? formatNumber(mom) : '-'}</td>}
                                {index > 0 && <td className={`px-4 py-4 text-right ${momColor}`}>{momPercent !== undefined ? formatNumber(momPercent, 2) : '-'}</td>}
                            </React.Fragment>
                            );
                        })}
                    </tr>
                    {isExpanded && (
                        <tr className="bg-gray-900">
                            <td colSpan={2 + months.length * 3} className="p-4">
                                <div className="rounded-lg overflow-hidden border border-gray-700">
                                    <div className="bg-gray-800 px-4 py-2 border-b border-gray-700 flex justify-between items-center">
                                        <span className="text-sm font-semibold text-blue-400">{account.accountName} - {focusMonth} 產品費用明細</span>
                                    </div>
                                    <table className="w-full text-xs text-left">
                                        <thead className="bg-gray-700 text-gray-300 uppercase">
                                            <tr>
                                                <th className="px-4 py-2">產品名稱 (Product Name)</th>
                                                <th className="px-4 py-2 text-right">上月費用 (USD)</th>
                                                <th className="px-4 py-2 text-right">本月費用 (USD)</th>
                                                <th className="px-4 py-2 text-right">變動值 (MoM USD)</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {getAccountServiceDetails(account.accountId).map((s, idx) => (
                                                <tr key={idx} className="border-b border-gray-800 hover:bg-gray-850">
                                                    <td className="px-4 py-2 text-gray-200">{s.productName}</td>
                                                    <td className="px-4 py-2 text-right">{formatNumber(s.prevCost)}</td>
                                                    <td className="px-4 py-2 text-right text-white font-medium">{formatNumber(s.currentCost)}</td>
                                                    <td className={`px-4 py-2 text-right font-semibold ${s.diff > 0 ? 'text-red-400' : s.diff < 0 ? 'text-green-400' : 'text-gray-500'}`}>
                                                        {s.diff > 0 ? '+' : ''}{formatNumber(s.diff)}
                                                    </td>
                                                </tr>
                                            ))}
                                            {getAccountServiceDetails(account.accountId).length === 0 && (
                                                <tr>
                                                    <td colSpan={4} className="px-4 py-4 text-center text-gray-500">此帳號在選擇月份無使用資料</td>
                                                </tr>
                                            )}
                                        </tbody>
                                    </table>
                                </div>
                            </td>
                        </tr>
                    )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

export default DashboardTab;

import React, { useMemo, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { BillingData } from '../types';
import { exportToExcel } from '../services/excelUtils';
import Card from './common/Card';

interface DashboardTabProps {
  data: BillingData;
}

const formatNumber = (value: number, decimals: number = 2) => {
    if (typeof value !== 'number' || isNaN(value)) return '0.00';
    return new Intl.NumberFormat('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }).format(value);
};

const DashboardTab: React.FC<DashboardTabProps> = ({ data }) => {
  const sortedData = useMemo(() => [...data].sort((a, b) => a.month.localeCompare(b.month)), [data]);
  const months = useMemo(() => sortedData.map(d => d.month), [sortedData]);

  // 狀態：月份選擇、展開的帳號、展開的產品
  const [focusMonth, setFocusMonth] = useState<string>(months[months.length - 1] || '');
  const [expandedAccountId, setExpandedAccountId] = useState<string | null>(null);
  const [expandedProductKey, setExpandedProductKey] = useState<string | null>(null);

  const monthlyTotalData = useMemo(() => {
    return sortedData.map(monthData => ({
      month: monthData.month,
      'Total Amount of Payment (USD)': monthData.totalAmount,
    }));
  }, [sortedData]);

  const totalCumulativeAmount = useMemo(() => {
    return sortedData.reduce((sum, monthData) => sum + monthData.totalAmount, 0);
  }, [sortedData]);

  const perAccountChangesData = useMemo(() => {
    const allAccounts = new Map<string, { accountName: string; monthlyTotals: { [month: string]: number } }>();

    sortedData.forEach(monthData => {
      monthData.accounts.forEach(account => {
        if (!allAccounts.has(account.accountId)) {
          allAccounts.set(account.accountId, { accountName: account.accountName, monthlyTotals: {} });
        }
        const acc = allAccounts.get(account.accountId)!;
        acc.monthlyTotals[monthData.month] = account.totalAmount;
      });
    });

    return Array.from(allAccounts.entries()).map(([accountId, data]) => ({
      accountId,
      accountName: data.accountName,
      monthlyTotals: data.monthlyTotals
    }));
  }, [sortedData]);

  // 計算特定帳號在 focusMonth 的產品明細 (二階)
  const getAccountServiceDetails = (accountId: string) => {
    const currentMonthData = sortedData.find(d => d.month === focusMonth);
    const prevMonthIndex = months.indexOf(focusMonth) - 1;
    const prevMonth = prevMonthIndex >= 0 ? months[prevMonthIndex] : null;
    const prevMonthData = prevMonth ? sortedData.find(d => d.month === prevMonth) : null;

    const currentAccount = currentMonthData?.accounts.find(a => a.accountId === accountId);
    const prevAccount = prevMonthData?.accounts.find(a => a.accountId === accountId);

    const services = new Map<string, { current: number; prev: number }>();

    currentAccount?.services.forEach(s => {
      services.set(s.productName, { current: s.totalCost, prev: 0 });
    });

    prevAccount?.services.forEach(s => {
      const existing = services.get(s.productName) || { current: 0, prev: 0 };
      services.set(s.productName, { ...existing, prev: s.totalCost });
    });

    return Array.from(services.entries())
      .map(([name, costs]) => ({
        productName: name,
        currentCost: costs.current,
        prevCost: costs.prev,
        diff: costs.current - costs.prev
      }))
      .sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff));
  };

  // 計算特定產品的使用類型明細 (三階)
  const getServiceUsageDetails = (accountId: string, productName: string) => {
    const currentMonthData = sortedData.find(d => d.month === focusMonth);
    const prevMonthIndex = months.indexOf(focusMonth) - 1;
    const prevMonth = prevMonthIndex >= 0 ? months[prevMonthIndex] : null;
    const prevMonthData = prevMonth ? sortedData.find(d => d.month === prevMonth) : null;

    const currentService = currentMonthData?.accounts.find(a => a.accountId === accountId)?.services.find(s => s.productName === productName);
    const prevService = prevMonthData?.accounts.find(a => a.accountId === accountId)?.services.find(s => s.productName === productName);

    const usageMap = new Map<string, { currentUsage: number; prevUsage: number; currentCost: number; prevCost: number; usageType: string; itemDescription: string }>();

    currentService?.details.forEach(d => {
      const key = `${d.usageType}|||${d.itemDescription}`;
      usageMap.set(key, { 
        currentUsage: d.usages, 
        prevUsage: 0, 
        currentCost: d.totalCost, 
        prevCost: 0,
        usageType: d.usageType,
        itemDescription: d.itemDescription
      });
    });

    prevService?.details.forEach(d => {
      const key = `${d.usageType}|||${d.itemDescription}`;
      const existing = usageMap.get(key) || { currentUsage: 0, prevUsage: 0, currentCost: 0, prevCost: 0, usageType: d.usageType, itemDescription: d.itemDescription };
      usageMap.set(key, {
        ...existing,
        prevUsage: d.usages,
        prevCost: d.totalCost
      });
    });

    return Array.from(usageMap.values()).sort((a, b) => Math.abs(b.currentCost - b.prevCost) - Math.abs(a.currentCost - a.prevCost));
  };

  const handleExport = () => {
      const exportData = perAccountChangesData.map(account => {
        const row: any = {
          'Account ID': account.accountId,
          'Account Name': account.accountName,
        };
        months.forEach((month, index) => {
          const total = account.monthlyTotals[month] ?? 0;
          row[`${month} (USD)`] = total.toFixed(2);
        });
        return row;
      });
      exportToExcel(exportData, `account_cost_summary`);
  };

  return (
    <div className="space-y-8">
      <Card title="總覽與每月趨勢">
        <div className="mb-6 p-4 bg-gray-700 rounded-lg">
          <h4 className="text-lg font-semibold text-white">累計總支付金額 (Total Amount of Payment)</h4>
          <p className="text-3xl font-bold text-blue-400">{formatNumber(totalCumulativeAmount)} (USD)</p>
        </div>
        <div className="h-96">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={monthlyTotalData} margin={{ top: 5, right: 30, left: 50, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#4a5568" />
              <XAxis dataKey="month" stroke="#a0aec0" />
              <YAxis stroke="#a0aec0" tickFormatter={(value) => Number(value).toLocaleString()} />
              <Tooltip
                contentStyle={{ backgroundColor: '#2d3748', border: 'none', borderRadius: '0.5rem' }}
                labelStyle={{ color: '#e2e8f0' }}
                formatter={(value:number) => [formatNumber(value), 'Total Amount of Payment']}
              />
              <Legend wrapperStyle={{color: '#a0aec0'}} />
              <Line type="monotone" dataKey="Total Amount of Payment (USD)" stroke="#4299e1" strokeWidth={2} activeDot={{ r: 8 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </Card>

      <Card title="每個帳號的金額變化" actionButton={perAccountChangesData.length > 0 && <button onClick={handleExport} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded text-sm transition-colors">匯出總表</button>}>
        <div className="mb-4 p-4 bg-gray-700 rounded-lg flex items-center flex-wrap gap-4">
            <div className="flex items-center space-x-2">
                <label htmlFor="focus-month-select" className="text-sm font-medium text-gray-300">分析基準月份:</label>
                <select
                    id="focus-month-select"
                    value={focusMonth}
                    onChange={(e) => {
                        setFocusMonth(e.target.value);
                        setExpandedAccountId(null);
                        setExpandedProductKey(null);
                    }}
                    className="bg-gray-800 border border-gray-600 text-white text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2"
                >
                    {months.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>
            <span className="text-xs text-gray-400">階層說明：點擊帳號列 ▶ 產品列 ▶ 使用類型明細</span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left text-gray-400">
            <thead className="text-xs text-gray-300 uppercase bg-gray-700 sticky top-0">
              <tr>
                <th scope="col" className="px-4 py-3">Account ID</th>
                <th scope="col" className="px-4 py-3">Account Name</th>
                {months.map((month, index) => (
                  <React.Fragment key={month}>
                    <th scope="col" className="px-4 py-3 text-right">{month} (USD)</th>
                    {index > 0 && <th scope="col" className="px-4 py-3 text-right">MoM (USD)</th>}
                  </React.Fragment>
                ))}
              </tr>
            </thead>
            <tbody>
              {perAccountChangesData.map(account => {
                const isAccExpanded = expandedAccountId === account.accountId;
                return (
                  <React.Fragment key={account.accountId}>
                    <tr 
                        className={`bg-gray-800 border-b border-gray-700 hover:bg-gray-700 cursor-pointer transition-colors ${isAccExpanded ? 'bg-gray-750' : ''}`}
                        onClick={() => {
                            setExpandedAccountId(isAccExpanded ? null : account.accountId);
                            setExpandedProductKey(null);
                        }}
                    >
                        <td className="px-4 py-4 font-medium text-white whitespace-nowrap">
                            <span className={`inline-block w-4 transition-transform duration-200 ${isAccExpanded ? 'rotate-90' : ''}`}>▶</span>
                            <span className="ml-2">{account.accountId}</span>
                        </td>
                        <td className="px-4 py-4 text-gray-300">{account.accountName}</td>
                        {months.map((month, index) => {
                            const total = account.monthlyTotals[month] ?? 0;
                            let mom, momColor;
                            if (index > 0) {
                                const prevMonth = months[index - 1];
                                const prevTotal = account.monthlyTotals[prevMonth] ?? 0;
                                mom = total - prevTotal;
                                momColor = mom > 0 ? 'text-red-400' : mom < 0 ? 'text-green-400' : 'text-gray-400';
                            }
                            return (
                                <React.Fragment key={month}>
                                    <td className="px-4 py-4 text-right">{formatNumber(total)}</td>
                                    {index > 0 && <td className={`px-4 py-4 text-right ${momColor}`}>{mom !== undefined ? formatNumber(mom) : '-'}</td>}
                                </React.Fragment>
                            );
                        })}
                    </tr>
                    {isAccExpanded && (
                        <tr className="bg-gray-900">
                            <td colSpan={2 + months.length * 2} className="p-4">
                                <div className="rounded-lg overflow-hidden border border-gray-700 bg-gray-800">
                                    <div className="px-4 py-2 border-b border-gray-700 bg-gray-750">
                                        <span className="text-sm font-semibold text-blue-400">{account.accountName} ({focusMonth}) - 產品費用概覽</span>
                                    </div>
                                    <table className="w-full text-xs text-left">
                                        <thead className="bg-gray-700 text-gray-300 uppercase">
                                            <tr>
                                                <th className="px-4 py-2">產品名稱 (Product)</th>
                                                <th className="px-4 py-2 text-right">上月費用</th>
                                                <th className="px-4 py-2 text-right">本月費用</th>
                                                <th className="px-4 py-2 text-right">變動值 (MoM)</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {getAccountServiceDetails(account.accountId).map((s, idx) => {
                                                const productKey = `${account.accountId}-${s.productName}`;
                                                const isProdExpanded = expandedProductKey === productKey;
                                                return (
                                                    <React.Fragment key={idx}>
                                                        <tr 
                                                            className={`border-b border-gray-700 hover:bg-gray-700 cursor-pointer transition-colors ${isProdExpanded ? 'bg-gray-700' : ''}`}
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                setExpandedProductKey(isProdExpanded ? null : productKey);
                                                            }}
                                                        >
                                                            <td className="px-4 py-2 text-gray-200">
                                                                <span className={`inline-block w-4 transition-transform duration-200 ${isProdExpanded ? 'rotate-90' : ''}`}>▶</span>
                                                                <span className="ml-2">{s.productName}</span>
                                                            </td>
                                                            <td className="px-4 py-2 text-right text-gray-400">{formatNumber(s.prevCost)}</td>
                                                            <td className="px-4 py-2 text-right text-white font-medium">{formatNumber(s.currentCost)}</td>
                                                            <td className={`px-4 py-2 text-right font-semibold ${s.diff > 0 ? 'text-red-400' : s.diff < 0 ? 'text-green-400' : 'text-gray-500'}`}>
                                                                {s.diff > 0 ? '+' : ''}{formatNumber(s.diff)}
                                                            </td>
                                                        </tr>
                                                        {isProdExpanded && (
                                                            <tr className="bg-black/30">
                                                                <td colSpan={4} className="p-3">
                                                                    <div className="bg-gray-900/50 rounded p-2 border border-gray-700">
                                                                        <div className="text-[10px] text-gray-500 uppercase mb-2 font-bold tracking-wider">細節項目比較 (Usage Type Details)</div>
                                                                        <table className="w-full text-[11px]">
                                                                            <thead className="text-gray-500 border-b border-gray-800">
                                                                                <tr>
                                                                                    <th className="pb-1 text-left">Usage Type / Item Description</th>
                                                                                    <th className="pb-1 text-right">上月用量</th>
                                                                                    <th className="pb-1 text-right">本月用量</th>
                                                                                    <th className="pb-1 text-right">用量差異</th>
                                                                                    <th className="pb-1 text-right">本月費用 (USD)</th>
                                                                                    <th className="pb-1 text-right">費用差異 (USD)</th>
                                                                                </tr>
                                                                            </thead>
                                                                            <tbody>
                                                                                {getServiceUsageDetails(account.accountId, s.productName).map((u, uIdx) => {
                                                                                    const usageDiff = u.currentUsage - u.prevUsage;
                                                                                    const costDiff = u.currentCost - u.prevCost;
                                                                                    return (
                                                                                        <tr key={uIdx} className="border-b border-gray-800/50 last:border-0">
                                                                                            <td className="py-1.5 pr-4">
                                                                                                <div className="text-gray-300 font-medium">{u.usageType}</div>
                                                                                                <div className="text-gray-500 italic">{u.itemDescription}</div>
                                                                                            </td>
                                                                                            <td className="py-1.5 text-right text-gray-400">{formatNumber(u.prevUsage, 4)}</td>
                                                                                            <td className="py-1.5 text-right text-gray-200">{formatNumber(u.currentUsage, 4)}</td>
                                                                                            <td className={`py-1.5 text-right ${usageDiff > 0 ? 'text-red-300' : usageDiff < 0 ? 'text-green-300' : 'text-gray-600'}`}>
                                                                                                {usageDiff > 0 ? '+' : ''}{formatNumber(usageDiff, 4)}
                                                                                            </td>
                                                                                            <td className="py-1.5 text-right text-blue-300 font-semibold">{formatNumber(u.currentCost)}</td>
                                                                                            <td className={`py-1.5 text-right ${costDiff > 0 ? 'text-red-400' : costDiff < 0 ? 'text-green-400' : 'text-gray-600'}`}>
                                                                                                {costDiff > 0 ? '+' : ''}{formatNumber(costDiff)}
                                                                                            </td>
                                                                                        </tr>
                                                                                    );
                                                                                })}
                                                                            </tbody>
                                                                        </table>
                                                                    </div>
                                                                </td>
                                                            </tr>
                                                        )}
                                                    </React.Fragment>
                                                );
                                            })}
                                        </tbody>
                                    </table>
                                </div>
                            </td>
                        </tr>
                    )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

export default DashboardTab;

import React, { useMemo, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { BillingData } from '../types';
import { exportToExcel } from '../services/excelUtils';
import Card from './common/Card';

interface DashboardTabProps {
  data: BillingData;
}

const formatNumber = (value: number, decimals: number = 2) => {
    if (typeof value !== 'number' || isNaN(value)) return '0.00';
    return new Intl.NumberFormat('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }).format(value);
};

type SortKey = 'accountId' | 'accountName' | 'currentAmount' | 'currentMom';
type SortDirection = 'asc' | 'desc';

const DashboardTab: React.FC<DashboardTabProps> = ({ data }) => {
  const sortedData = useMemo(() => [...data].sort((a, b) => a.month.localeCompare(b.month)), [data]);
  const months = useMemo(() => sortedData.map(d => d.month), [sortedData]);

  // 狀態：月份選擇、展開的帳號、展開的產品、排序設定
  const [focusMonth, setFocusMonth] = useState<string>(months[months.length - 1] || '');
  const [expandedAccountId, setExpandedAccountId] = useState<string | null>(null);
  const [expandedProductKey, setExpandedProductKey] = useState<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection }>({
    key: 'currentAmount',
    direction: 'desc'
  });

  const monthlyTotalData = useMemo(() => {
    return sortedData.map(monthData => ({
      month: monthData.month,
      'Total Amount of Payment (USD)': monthData.totalAmount,
    }));
  }, [sortedData]);

  const totalCumulativeAmount = useMemo(() => {
    return sortedData.reduce((sum, monthData) => sum + monthData.totalAmount, 0);
  }, [sortedData]);

  const perAccountChangesData = useMemo(() => {
    const allAccounts = new Map<string, { accountName: string; monthlyTotals: { [month: string]: number } }>();

    sortedData.forEach(monthData => {
      monthData.accounts.forEach(account => {
        if (!allAccounts.has(account.accountId)) {
          allAccounts.set(account.accountId, { accountName: account.accountName, monthlyTotals: {} });
        }
        const acc = allAccounts.get(account.accountId)!;
        acc.monthlyTotals[monthData.month] = account.totalAmount;
      });
    });

    return Array.from(allAccounts.entries()).map(([accountId, data]) => ({
      accountId,
      accountName: data.accountName,
      monthlyTotals: data.monthlyTotals
    }));
  }, [sortedData]);

  // 核心排序邏輯
  const sortedAccounts = useMemo(() => {
    const prevMonthIndex = months.indexOf(focusMonth) - 1;
    const prevMonth = prevMonthIndex >= 0 ? months[prevMonthIndex] : null;

    return [...perAccountChangesData].sort((a, b) => {
      let valA: any, valB: any;

      switch (sortConfig.key) {
        case 'accountId':
          valA = a.accountId;
          valB = b.accountId;
          break;
        case 'accountName':
          valA = a.accountName;
          valB = b.accountName;
          break;
        case 'currentAmount':
          valA = a.monthlyTotals[focusMonth] || 0;
          valB = b.monthlyTotals[focusMonth] || 0;
          break;
        case 'currentMom':
          const currentA = a.monthlyTotals[focusMonth] || 0;
          const prevA = prevMonth ? (a.monthlyTotals[prevMonth] || 0) : 0;
          const currentB = b.monthlyTotals[focusMonth] || 0;
          const prevB = prevMonth ? (b.monthlyTotals[prevMonth] || 0) : 0;
          valA = currentA - prevA;
          valB = currentB - prevB;
          break;
        default:
          return 0;
      }

      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [perAccountChangesData, sortConfig, focusMonth, months]);

  const handleSort = (key: SortKey) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'desc' ? 'asc' : 'desc'
    }));
  };

  const getSortIcon = (key: SortKey) => {
    if (sortConfig.key !== key) return '↕';
    return sortConfig.direction === 'asc' ? '↑' : '↓';
  };

  // 計算產品明細 (二階) 與 使用類型明細 (三階) 邏輯保持不變...
  const getAccountServiceDetails = (accountId: string) => {
    const currentMonthData = sortedData.find(d => d.month === focusMonth);
    const prevMonthIndex = months.indexOf(focusMonth) - 1;
    const prevMonth = prevMonthIndex >= 0 ? months[prevMonthIndex] : null;
    const prevMonthData = prevMonth ? sortedData.find(d => d.month === prevMonth) : null;
    const currentAccount = currentMonthData?.accounts.find(a => a.accountId === accountId);
    const prevAccount = prevMonthData?.accounts.find(a => a.accountId === accountId);
    const services = new Map<string, { current: number; prev: number }>();
    currentAccount?.services.forEach(s => { services.set(s.productName, { current: s.totalCost, prev: 0 }); });
    prevAccount?.services.forEach(s => {
      const existing = services.get(s.productName) || { current: 0, prev: 0 };
      services.set(s.productName, { ...existing, prev: s.totalCost });
    });
    return Array.from(services.entries())
      .map(([name, costs]) => ({ productName: name, currentCost: costs.current, prevCost: costs.prev, diff: costs.current - costs.prev }))
      .sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff));
  };

  const getServiceUsageDetails = (accountId: string, productName: string) => {
    const currentMonthData = sortedData.find(d => d.month === focusMonth);
    const prevMonthIndex = months.indexOf(focusMonth) - 1;
    const prevMonth = prevMonthIndex >= 0 ? months[prevMonthIndex] : null;
    const prevMonthData = prevMonth ? sortedData.find(d => d.month === prevMonth) : null;
    const currentService = currentMonthData?.accounts.find(a => a.accountId === accountId)?.services.find(s => s.productName === productName);
    const prevService = prevMonthData?.accounts.find(a => a.accountId === accountId)?.services.find(s => s.productName === productName);
    const usageMap = new Map<string, { currentUsage: number; prevUsage: number; currentCost: number; prevCost: number; usageType: string; itemDescription: string }>();
    currentService?.details.forEach(d => {
      const key = `${d.usageType}|||${d.itemDescription}`;
      usageMap.set(key, { currentUsage: d.usages, prevUsage: 0, currentCost: d.totalCost, prevCost: 0, usageType: d.usageType, itemDescription: d.itemDescription });
    });
    prevService?.details.forEach(d => {
      const key = `${d.usageType}|||${d.itemDescription}`;
      const existing = usageMap.get(key) || { currentUsage: 0, prevUsage: 0, currentCost: 0, prevCost: 0, usageType: d.usageType, itemDescription: d.itemDescription };
      usageMap.set(key, { ...existing, prevUsage: d.usages, prevCost: d.totalCost });
    });
    return Array.from(usageMap.values()).sort((a, b) => Math.abs(b.currentCost - b.prevCost) - Math.abs(a.currentCost - a.prevCost));
  };

  const handleExport = () => {
      const exportData = sortedAccounts.map(account => {
        const row: any = { 'Account ID': account.accountId, 'Account Name': account.accountName };
        months.forEach(month => { row[`${month} (USD)`] = (account.monthlyTotals[month] ?? 0).toFixed(2); });
        return row;
      });
      exportToExcel(exportData, `account_cost_summary_sorted`);
  };

  return (
    <div className="space-y-8">
      <Card title="總覽與每月趨勢">
        <div className="mb-6 p-4 bg-gray-700 rounded-lg">
          <h4 className="text-lg font-semibold text-white">累計總支付金額 (Total Amount of Payment)</h4>
          <p className="text-3xl font-bold text-blue-400">{formatNumber(totalCumulativeAmount)} (USD)</p>
        </div>
        <div className="h-96">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={monthlyTotalData} margin={{ top: 5, right: 30, left: 50, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#4a5568" />
              <XAxis dataKey="month" stroke="#a0aec0" />
              <YAxis stroke="#a0aec0" tickFormatter={(value) => Number(value).toLocaleString()} />
              <Tooltip
                contentStyle={{ backgroundColor: '#2d3748', border: 'none', borderRadius: '0.5rem' }}
                labelStyle={{ color: '#e2e8f0' }}
                formatter={(value:number) => [formatNumber(value), 'Total Amount of Payment']}
              />
              <Legend wrapperStyle={{color: '#a0aec0'}} />
              <Line type="monotone" dataKey="Total Amount of Payment (USD)" stroke="#4299e1" strokeWidth={2} activeDot={{ r: 8 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </Card>

      <Card title="每個帳號的金額變化" actionButton={sortedAccounts.length > 0 && <button onClick={handleExport} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded text-sm transition-colors">匯出總表</button>}>
        <div className="mb-4 p-4 bg-gray-700 rounded-lg flex items-center flex-wrap gap-4">
            <div className="flex items-center space-x-2 mr-4">
                <label htmlFor="focus-month-select" className="text-sm font-medium text-gray-300">分析基準月份:</label>
                <select
                    id="focus-month-select"
                    value={focusMonth}
                    onChange={(e) => {
                        setFocusMonth(e.target.value);
                        setExpandedAccountId(null);
                        setExpandedProductKey(null);
                    }}
                    className="bg-gray-800 border border-gray-600 text-white text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2"
                >
                    {months.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="flex items-center space-x-2 border-l border-gray-600 pl-4">
                <span className="text-sm font-medium text-gray-300">基準月排序:</span>
                <button 
                    onClick={() => handleSort('currentAmount')}
                    className={`px-3 py-1 text-xs rounded transition-colors ${sortConfig.key === 'currentAmount' ? 'bg-blue-600 text-white' : 'bg-gray-800 text-gray-400 hover:bg-gray-600'}`}
                >
                    依金額 {getSortIcon('currentAmount')}
                </button>
                <button 
                    onClick={() => handleSort('currentMom')}
                    className={`px-3 py-1 text-xs rounded transition-colors ${sortConfig.key === 'currentMom' ? 'bg-blue-600 text-white' : 'bg-gray-800 text-gray-400 hover:bg-gray-600'}`}
                >
                    依變動量 (MoM) {getSortIcon('currentMom')}
                </button>
            </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left text-gray-400">
            <thead className="text-xs text-gray-300 uppercase bg-gray-700 sticky top-0">
              <tr>
                <th scope="col" className="px-4 py-3 cursor-pointer hover:bg-gray-600 transition-colors" onClick={() => handleSort('accountId')}>
                  Account ID <span className="ml-1 text-blue-400">{getSortIcon('accountId')}</span>
                </th>
                <th scope="col" className="px-4 py-3 cursor-pointer hover:bg-gray-600 transition-colors" onClick={() => handleSort('accountName')}>
                  Account Name <span className="ml-1 text-blue-400">{getSortIcon('accountName')}</span>
                </th>
                {months.map((month, index) => {
                  const isFocused = month === focusMonth;
                  return (
                    <React.Fragment key={month}>
                        <th scope="col" className={`px-4 py-3 text-right ${isFocused ? 'bg-blue-900/30 text-blue-200' : ''}`}>
                            {month} (USD)
                        </th>
                        {index > 0 && (
                            <th scope="col" className={`px-4 py-3 text-right ${isFocused ? 'bg-blue-900/30 text-blue-200' : ''}`}>
                                MoM (USD)
                            </th>
                        )}
                    </React.Fragment>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {sortedAccounts.map(account => {
                const isAccExpanded = expandedAccountId === account.accountId;
                return (
                  <React.Fragment key={account.accountId}>
                    <tr 
                        className={`bg-gray-800 border-b border-gray-700 hover:bg-gray-700 cursor-pointer transition-colors ${isAccExpanded ? 'bg-gray-750' : ''}`}
                        onClick={() => {
                            setExpandedAccountId(isAccExpanded ? null : account.accountId);
                            setExpandedProductKey(null);
                        }}
                    >
                        <td className="px-4 py-4 font-medium text-white whitespace-nowrap">
                            <span className={`inline-block w-4 transition-transform duration-200 ${isAccExpanded ? 'rotate-90' : ''}`}>▶</span>
                            <span className="ml-2">{account.accountId}</span>
                        </td>
                        <td className="px-4 py-4 text-gray-300">{account.accountName}</td>
                        {months.map((month, index) => {
                            const total = account.monthlyTotals[month] ?? 0;
                            const isFocused = month === focusMonth;
                            let mom, momColor;
                            if (index > 0) {
                                const prevMonth = months[index - 1];
                                const prevTotal = account.monthlyTotals[prevMonth] ?? 0;
                                mom = total - prevTotal;
                                momColor = mom > 0 ? 'text-red-400' : mom < 0 ? 'text-green-400' : 'text-gray-400';
                            }
                            return (
                                <React.Fragment key={month}>
                                    <td className={`px-4 py-4 text-right ${isFocused ? 'bg-blue-900/10 font-bold text-white' : ''}`}>{formatNumber(total)}</td>
                                    {index > 0 && <td className={`px-4 py-4 text-right ${isFocused ? 'bg-blue-900/10 font-bold' : ''} ${momColor}`}>{mom !== undefined ? formatNumber(mom) : '-'}</td>}
                                </React.Fragment>
                            );
                        })}
                    </tr>
                    {isAccExpanded && (
                        <tr className="bg-gray-900">
                            <td colSpan={2 + months.length * 2} className="p-4">
                                <div className="rounded-lg overflow-hidden border border-gray-700 bg-gray-800 shadow-xl">
                                    <div className="px-4 py-2 border-b border-gray-700 bg-gray-750 flex justify-between items-center">
                                        <span className="text-sm font-semibold text-blue-400">{account.accountName} ({focusMonth}) - 產品費用概覽</span>
                                        <span className="text-xs text-gray-500 italic">點擊下方產品可查看更詳細的 Usage Type 分佈</span>
                                    </div>
                                    <table className="w-full text-xs text-left">
                                        <thead className="bg-gray-700 text-gray-300 uppercase">
                                            <tr>
                                                <th className="px-4 py-2">產品名稱 (Product)</th>
                                                <th className="px-4 py-2 text-right">上月費用</th>
                                                <th className="px-4 py-2 text-right">本月費用</th>
                                                <th className="px-4 py-2 text-right">變動值 (MoM)</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {getAccountServiceDetails(account.accountId).map((s, idx) => {
                                                const productKey = `${account.accountId}-${s.productName}`;
                                                const isProdExpanded = expandedProductKey === productKey;
                                                return (
                                                    <React.Fragment key={idx}>
                                                        <tr 
                                                            className={`border-b border-gray-700 hover:bg-gray-700 cursor-pointer transition-colors ${isProdExpanded ? 'bg-gray-700' : ''}`}
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                setExpandedProductKey(isProdExpanded ? null : productKey);
                                                            }}
                                                        >
                                                            <td className="px-4 py-2 text-gray-200">
                                                                <span className={`inline-block w-4 transition-transform duration-200 ${isProdExpanded ? 'rotate-90' : ''}`}>▶</span>
                                                                <span className="ml-2">{s.productName}</span>
                                                            </td>
                                                            <td className="px-4 py-2 text-right text-gray-400">{formatNumber(s.prevCost)}</td>
                                                            <td className="px-4 py-2 text-right text-white font-medium">{formatNumber(s.currentCost)}</td>
                                                            <td className={`px-4 py-2 text-right font-semibold ${s.diff > 0 ? 'text-red-400' : s.diff < 0 ? 'text-green-400' : 'text-gray-500'}`}>
                                                                {s.diff > 0 ? '+' : ''}{formatNumber(s.diff)}
                                                            </td>
                                                        </tr>
                                                        {isProdExpanded && (
                                                            <tr className="bg-black/30">
                                                                <td colSpan={4} className="p-3">
                                                                    <div className="bg-gray-900/50 rounded p-2 border border-gray-700">
                                                                        <div className="text-[10px] text-gray-500 uppercase mb-2 font-bold tracking-wider">細節項目比較 (Usage Type Details)</div>
                                                                        <table className="w-full text-[11px]">
                                                                            <thead className="text-gray-500 border-b border-gray-800">
                                                                                <tr>
                                                                                    <th className="pb-1 text-left">Usage Type / Item Description</th>
                                                                                    <th className="pb-1 text-right">上月用量</th>
                                                                                    <th className="pb-1 text-right">本月用量</th>
                                                                                    <th className="pb-1 text-right">用量差異</th>
                                                                                    <th className="pb-1 text-right">本月費用 (USD)</th>
                                                                                    <th className="pb-1 text-right">費用差異 (USD)</th>
                                                                                </tr>
                                                                            </thead>
                                                                            <tbody>
                                                                                {getServiceUsageDetails(account.accountId, s.productName).map((u, uIdx) => {
                                                                                    const usageDiff = u.currentUsage - u.prevUsage;
                                                                                    const costDiff = u.currentCost - u.prevCost;
                                                                                    return (
                                                                                        <tr key={uIdx} className="border-b border-gray-800/50 last:border-0">
                                                                                            <td className="py-1.5 pr-4">
                                                                                                <div className="text-gray-300 font-medium">{u.usageType}</div>
                                                                                                <div className="text-gray-500 italic">{u.itemDescription}</div>
                                                                                            </td>
                                                                                            <td className="py-1.5 text-right text-gray-400">{formatNumber(u.prevUsage, 4)}</td>
                                                                                            <td className="py-1.5 text-right text-gray-200">{formatNumber(u.currentUsage, 4)}</td>
                                                                                            <td className={`py-1.5 text-right ${usageDiff > 0 ? 'text-red-300' : usageDiff < 0 ? 'text-green-300' : 'text-gray-600'}`}>
                                                                                                {usageDiff > 0 ? '+' : ''}{formatNumber(usageDiff, 4)}
                                                                                            </td>
                                                                                            <td className="py-1.5 text-right text-blue-300 font-semibold">{formatNumber(u.currentCost)}</td>
                                                                                            <td className={`py-1.5 text-right ${costDiff > 0 ? 'text-red-400' : costDiff < 0 ? 'text-green-400' : 'text-gray-600'}`}>
                                                                                                {costDiff > 0 ? '+' : ''}{formatNumber(costDiff)}
                                                                                            </td>
                                                                                        </tr>
                                                                                    );
                                                                                })}
                                                                            </tbody>
                                                                        </table>
                                                                    </div>
                                                                </td>
                                                            </tr>
                                                        )}
                                                    </React.Fragment>
                                                );
                                            })}
                                        </tbody>
                                    </table>
                                </div>
                            </td>
                        </tr>
                    )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

